jsonTools.init:
function init(eli) {
  function _esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  var DEFAULT_SCHEMA = {
    contractTitle: "Colgate-Palmolive Company and [counterparty]",
    thirdPartyPI: null,
    publicationClause: {
      summary: "1-2 sentence summary of publication rights/restrictions",
      keyTerms: ["Review period: e.g. 30 days", "Approval required: yes/no"],
    },
    contacts: [
      { name: "...", role: "PI / Sponsor / Legal", email: "..." },
    ],
    otherNotable: "Short note on anything else publication-relevant",
  };

  function _launch() {
    // Reset session state
    window._igTemplate = null;
    window._igConfirmed = false;
    window._igResult = null;

    var out = eli.ui.claimOutput();
    out.classList.add("eli-view-enter");
    if (out.style) { out.style.justifyContent = "flex-start"; out.style.alignItems = "stretch"; }
    out.innerHTML =
      '<div style="display:flex;flex-direction:column;min-height:100vh;background:#f8f9fa;font-family:Inter,sans-serif;">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;border-bottom:1px solid #e2e8f0;background:#fff;flex-shrink:0;">' +
          '<button id="_ig_back" type="button" style="background:none;border:none;color:#64748b;cursor:pointer;font:800 11px/1 Inter,sans-serif;letter-spacing:1px;display:flex;align-items:center;gap:6px;">' +
            '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M19 12H5M12 19l-7-7 7-7"/></svg> BACK' +
          '</button>' +
          '<div style="font:700 13px/1 Inter,sans-serif;color:#1565c0;">Infographics Lab</div>' +
        '</div>' +
        '<div style="padding:14px 16px;background:linear-gradient(135deg,#0d1b2a,#1b263b);color:#fff;">' +
          '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.12em;text-transform:uppercase;color:#c9a227;">Admin · Test · Publications</div>' +
          '<div style="font:800 17px/1.2 Inter,sans-serif;margin-top:2px;">🎨 Publications infographic generator</div>' +
        '</div>' +
        '<div style="padding:14px 16px;flex:1;overflow-y:auto;">' +

          // ─── Step 1: Extract ───────────────────────────────────────
          '<div style="background:#fff;border:1px solid #e2e8f0;padding:12px 14px;margin-bottom:12px;">' +
            '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">' +
              '<div style="font:800 10px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1565c0;">Step 1 · Extract publication details from doc</div>' +
              '<button id="_ig_extract" type="button" style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:6px 12px;background:#7c3aed;color:#fff;border:none;cursor:pointer;">🔍 Extract from active doc</button>' +
            '</div>' +
            '<div id="_ig_extract_hint" style="font:500 11px/1.4 Inter,sans-serif;color:#64748b;">Click <b>Extract</b> to pull contract title, PI, publication clause, contacts, and other notable details.</div>' +
          '</div>' +

          // ─── Step 2: Confirm ───────────────────────────────────────
          '<div id="_ig_confirm_section" style="background:#fff;border:1px solid #e2e8f0;padding:12px 14px;margin-bottom:12px;display:none;">' +
            '<div style="font:800 10px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1565c0;margin-bottom:8px;">Step 2 · Review and confirm extracted details</div>' +
            '<div style="font:500 11px/1.4 Inter,sans-serif;color:#64748b;margin-bottom:6px;">Edit the JSON below if anything looks wrong, then click <b>Confirm accurate</b>.</div>' +
            '<textarea id="_ig_extracted" rows="14" placeholder="' + _esc(JSON.stringify(DEFAULT_SCHEMA, null, 2)) + '" ' +
              'style="width:100%;padding:8px 10px;font:500 11px/1.4 ui-monospace,Consolas,monospace;border:1px solid #cbd5e1;box-sizing:border-box;resize:vertical;background:#fafafa;"></textarea>' +
            '<div style="display:flex;gap:8px;align-items:center;margin-top:10px;">' +
              '<button id="_ig_confirm" type="button" style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:9px 14px;background:#15803d;color:#fff;border:none;cursor:pointer;">✓ Confirm accurate</button>' +
              '<span id="_ig_confirm_state" style="font:500 11px/1.4 Inter,sans-serif;color:#94a3b8;"></span>' +
            '</div>' +
          '</div>' +

          // ─── Step 3: Template upload (locked until step 2 confirmed) ─
          '<div id="_ig_template_section" style="background:#fff;border:1px solid #e2e8f0;padding:12px 14px;margin-bottom:12px;display:none;">' +
            '<div style="font:800 10px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1565c0;margin-bottom:8px;">Step 3 · Pick template image</div>' +
            '<input id="_ig_file" type="file" accept="image/png,image/jpeg,image/webp" style="font:500 11px Inter,sans-serif;width:100%;">' +
            '<div id="_ig_template_preview_wrap" style="display:none;margin-top:10px;">' +
              '<img id="_ig_template_preview" alt="template preview" style="display:block;max-width:100%;max-height:180px;border:1px dashed #cbd5e1;background:#f1f5f9;">' +
              '<div id="_ig_template_meta" style="font:500 10px/1.4 ui-monospace,Consolas,monospace;color:#64748b;margin-top:4px;"></div>' +
            '</div>' +
          '</div>' +

          // ─── Step 4: Render ─────────────────────────────────────────
          '<div id="_ig_status" style="font:500 12px/1.4 Inter,sans-serif;color:#64748b;margin-bottom:10px;"></div>' +
          '<div style="display:flex;gap:8px;align-items:center;margin-bottom:14px;">' +
            '<button id="_ig_render" type="button" disabled style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;padding:10px 16px;background:#1565c0;color:#fff;border:none;cursor:pointer;opacity:0.5;">⚡ Step 4 · Render template</button>' +
            '<span id="_ig_model" style="font:500 11px/1.3 ui-monospace,Consolas,monospace;color:#94a3b8;"></span>' +
          '</div>' +

          // ─── Result ─────────────────────────────────────────────────
          '<div id="_ig_result_wrap" style="display:none;">' +
            '<div style="background:#fff;border:1px solid #e2e8f0;padding:14px;margin-bottom:14px;">' +
              '<img id="_ig_out" alt="generated infographic" style="display:block;max-width:100%;height:auto;border:1px dashed #cbd5e1;background:#f1f5f9;">' +
            '</div>' +
            '<div style="background:#fef3c7;border:1px solid #fde68a;padding:9px 12px;margin-bottom:10px;font:500 11px/1.5 Inter,sans-serif;color:#78350f;">' +
              '<b>💾 To save as a file:</b> right-click the image above → <b>Save image as…</b> → pick a location.' +
            '</div>' +
            '<div style="display:flex;flex-wrap:wrap;gap:8px;">' +
              '<button id="_ig_insert" type="button" style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:9px 13px;background:linear-gradient(135deg,#15803d,#166534);color:#fff;border:none;cursor:pointer;">📄 Insert into doc</button>' +
              '<button id="_ig_regen" type="button" style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:9px 13px;background:#fff;border:1px solid #cbd5e1;color:#1e293b;cursor:pointer;">🔁 Regenerate</button>' +
            '</div>' +
          '</div>' +
        '</div>' +
      '</div>';

    document.getElementById("_ig_back").onclick = function () {
      if (typeof window.showHome === "function") window.showHome();
    };

    try {
      var m = eli.settings && eli.settings.get && eli.settings.get("ai_image_model");
      document.getElementById("_ig_model").textContent = m
        ? "Image model: " + m
        : "Image model: (none set — go to Settings → 🖼 AI Image Model)";
    } catch (_e) {}

    if (!eli.ai || typeof eli.ai.editImage !== "function") {
      _setStatus("⚠️ Needs kernel apiVersion 2 (ai.editImage). Update your Script Lab snippet.", true);
      return;
    }

    document.getElementById("_ig_extract").onclick = _extract;
    document.getElementById("_ig_confirm").onclick = _confirm;
    document.getElementById("_ig_file").onchange = _onFilePick;
    document.getElementById("_ig_render").onclick = _render;
    document.getElementById("_ig_regen").onclick = _render;
    document.getElementById("_ig_insert").onclick = _insertIntoDoc;
  }

  function _setStatus(msg, isErr) {
    var el = document.getElementById("_ig_status");
    if (!el) return;
    el.innerHTML = msg;
    el.style.color = isErr ? "#b91c1c" : "#64748b";
  }

  function _maybeEnableRender() {
    var btn = document.getElementById("_ig_render");
    var ready = !!(window._igConfirmed && window._igTemplate);
    btn.disabled = !ready;
    btn.style.opacity = ready ? "1" : "0.5";
  }

  // ─── Step 1: Extract ────────────────────────────────────────────────
  function _extract() {
    var btn = document.getElementById("_ig_extract");
    btn.disabled = true; btn.style.opacity = "0.5"; btn.textContent = "⏳ Extracting…";
    _setStatus("⏳ Reading doc + asking text AI to extract publication fields…");

    eli.host.readText({}).then(function (text) {
      var clipped = String(text || "").slice(0, 8000);
      var prompt =
        "Extract publication-related information from this contract. " +
        "Focus on: publication rights, publication clauses, principal investigator (PI), " +
        "contact details, and contract identity. Return a JSON object with these fields:\n\n" +
        "{\n" +
        "  \"contractTitle\": <string — e.g. 'Colgate-Palmolive Company and [counterparty name]'. " +
              "Colgate side is always 'Colgate-Palmolive Company'>,\n" +
        "  \"thirdPartyPI\": <string OR null — the principal investigator's name from the third party, " +
              "if mentioned. Format: 'Dr. Jane Doe' or similar. NULL if no PI is named.>,\n" +
        "  \"publicationClause\": {\n" +
        "    \"summary\": <string — 1-2 sentence plain-English summary of what the publication " +
              "rights/restrictions are>,\n" +
        "    \"keyTerms\": <array of short strings — e.g. ['Review period: 30 days', " +
              "'Colgate approval required', 'Confidential info redaction allowed', 'Attribution: Colgate-Palmolive']>\n" +
        "  },\n" +
        "  \"contacts\": <array of { name, role, email } objects — contacts mentioned in the contract " +
              "relevant to publications (e.g., PI, sponsor rep, legal). Empty array if none.>,\n" +
        "  \"otherNotable\": <string — anything else publication-relevant, max 1 sentence. " +
              "Empty string if nothing else.>\n" +
        "}\n\n" +
        "RULES:\n" +
        "1. Use exact text from the contract. Don't invent.\n" +
        "2. Null/empty for missing fields — never guess.\n" +
        "3. Be concise. This output drives an infographic with limited space.\n\n" +
        "CONTRACT:\n" + clipped;

      return eli.ai.completeJSON(prompt);
    }).then(function (data) {
      // Show Step 2 + populate JSON
      document.getElementById("_ig_confirm_section").style.display = "block";
      var ta = document.getElementById("_ig_extracted");
      ta.value = JSON.stringify(data, null, 2);
      // Reset confirmation state if user re-extracts after confirming
      window._igConfirmed = false;
      document.getElementById("_ig_template_section").style.display = "none";
      document.getElementById("_ig_confirm_state").textContent = "";
      _maybeEnableRender();
      _setStatus("✅ Extracted. Review the JSON in Step 2.");
    }).catch(function (err) {
      _setStatus("⚠️ Extract failed: " + _esc(err && err.message), true);
      eli.log.event("tool", "infographics_lab_extract_failed", { msg: err && err.message });
    }).then(function () {
      btn.disabled = false; btn.style.opacity = "1"; btn.textContent = "🔍 Extract from active doc";
    });
  }

  // ─── Step 2: Confirm ────────────────────────────────────────────────
  function _confirm() {
    var raw = (document.getElementById("_ig_extracted").value || "").trim();
    if (!raw) {
      _setStatus("⚠️ No data to confirm — run Step 1 first.", true);
      return;
    }
    try { JSON.parse(raw); }
    catch (e) {
      _setStatus("⚠️ JSON is invalid — fix the syntax in Step 2 before confirming: " + _esc(e.message), true);
      return;
    }
    window._igConfirmed = true;
    document.getElementById("_ig_confirm_state").innerHTML = '<span style="color:#15803d;">✓ Confirmed — Step 3 unlocked below.</span>';
    document.getElementById("_ig_template_section").style.display = "block";
    _setStatus("Confirmed. Upload your template in Step 3 → click Render.");
    _maybeEnableRender();
  }

  // ─── Step 3: Template upload ───────────────────────────────────────
  function _onFilePick(ev) {
    var f = ev.target.files && ev.target.files[0];
    if (!f) return;
    var reader = new FileReader();
    reader.onload = function () {
      var raw = String(reader.result || "");
      var m = raw.match(/^data:([^;]+);base64,(.*)$/);
      if (!m) { _setStatus("⚠️ Couldn't read file as base64.", true); return; }
      window._igTemplate = { mimeType: m[1], base64: m[2], name: f.name, size: f.size };
      var img = document.getElementById("_ig_template_preview");
      img.src = raw;
      document.getElementById("_ig_template_preview_wrap").style.display = "block";
      document.getElementById("_ig_template_meta").textContent =
        f.name + " · " + m[1] + " · " + Math.round(f.size / 1024) + " KB";
      _setStatus("Template loaded. Click <b>⚡ Render template</b> below.");
      _maybeEnableRender();
    };
    reader.onerror = function () { _setStatus("⚠️ File read failed.", true); };
    reader.readAsDataURL(f);
  }

  // ─── Step 4: Render ─────────────────────────────────────────────────
  function _render() {
    var tpl = window._igTemplate;
    if (!tpl) { _setStatus("⚠️ Pick a template in Step 3.", true); return; }
    if (!window._igConfirmed) { _setStatus("⚠️ Confirm extracted data in Step 2 first.", true); return; }
    var raw = (document.getElementById("_ig_extracted").value || "").trim();
    var data;
    try { data = JSON.parse(raw); }
    catch (e) { _setStatus("⚠️ JSON invalid: " + _esc(e.message), true); return; }

    var btn = document.getElementById("_ig_render");
    var regen = document.getElementById("_ig_regen");
    btn.disabled = true; btn.style.opacity = "0.5"; btn.textContent = "⏳ Rendering…";
    if (regen) { regen.disabled = true; regen.style.opacity = "0.5"; }
    _setStatus("⏳ Asking image AI to render template with confirmed data…");

    var prompt =
      "Modify this infographic template by filling in the publication-related data below. " +
      "The template has these zones — place each field accordingly:\n\n" +
      "• TOP / HEADER ZONE — put the contractTitle (e.g. 'Colgate-Palmolive Company and [PI]')\n" +
      "• PUBLICATION CLAUSE ZONE (main body) — put publicationClause.summary as a short paragraph, " +
        "then publicationClause.keyTerms as a bullet list\n" +
      "• CONTACTS ZONE — list each contact as 'Name · Role · email'\n" +
      "• OTHER ZONE (small section) — put otherNotable\n\n" +
      "RULES:\n" +
      "1. Preserve template's layout, colors, fonts, icons, and graphic style EXACTLY.\n" +
      "2. Only swap text content. Don't redraw graphics.\n" +
      "3. If a field is null, empty, or empty array, LEAVE that template zone unchanged " +
         "(don't write 'null' or 'N/A').\n" +
      "4. If thirdPartyPI is null but contractTitle mentions a placeholder for it, " +
         "use the counterparty company name instead.\n" +
      "5. Keep text concise so it fits the template's existing spaces.\n\n" +
      "DATA TO INSERT:\n" + JSON.stringify(data, null, 2);

    eli.ai.editImage(tpl.base64, prompt, { mimeType: tpl.mimeType }).then(function (r) {
      window._igResult = r;
      var url = "data:" + (r.mimeType || "image/png") + ";base64," + r.base64;
      document.getElementById("_ig_out").src = url;
      document.getElementById("_ig_result_wrap").style.display = "block";
      _setStatus("✅ Rendered. Insert into doc, regenerate, or right-click to save.");
    }).catch(function (err) {
      _setStatus("⚠️ Render failed: " + _esc(err && err.message), true);
      eli.log.event("tool", "infographics_lab_render_failed", { msg: err && err.message });
    }).then(function () {
      btn.disabled = false; btn.textContent = "⚡ Step 4 · Render template";
      _maybeEnableRender();
      if (regen) { regen.disabled = false; regen.style.opacity = "1"; }
    });
  }

  function _insertIntoDoc() {
    var r = window._igResult; if (!r) return;
    if (typeof eli.host.insertImage !== "function") {
      _setStatus("⚠️ insertImage needs host apiVersion 4. Update your Script Lab snippet.", true);
      return;
    }
    eli.host.insertImage(r.base64, { position: "End" }).then(function () {
      if (window.showToast) window.showToast("✅ Inserted into doc", "ok");
    }).catch(function (err) {
      _setStatus("⚠️ Insert failed: " + _esc(err && err.message), true);
    });
  }

  eli.register({
    tile: { app_infographics_lab: _launch },
  });
  eli.log.event("tool", "infographics_lab_initialized", {});
}
